using System;using System.Data;using System.Drawing;using System.Linq;using System.Windows.Forms;using System.Collections.Generic;using System.Globalization;using System.IO;using DongA.Service;
namespace DongA.UI {
 public class MainForm:Form {
 readonly HrService service=new HrService(); readonly ComboBox tables=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=240};readonly DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AllowUserToAddRows=false};
 readonly TextBox search=new TextBox{Width=210};readonly ComboBox action=new ComboBox{Width=210,DropDownStyle=ComboBoxStyle.DropDownList};readonly TextBox id=new TextBox{Width=150};readonly TextBox signer=new TextBox{Width=140,Text="Giám đốc"};readonly DateTimePicker date=new DateTimePicker{Width=120,Format=DateTimePickerFormat.Short};
 public MainForm(){Text="ĐÔNG Á | Quản lý nhân sự – Bài 7";Width=1450;Height=850;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=95,Padding=new Padding(8),AutoScroll=true};Controls.Add(grid);Controls.Add(top);tables.Items.AddRange(service.Tables);top.Controls.Add(new Label{Text="Danh mục / hồ sơ",AutoSize=true});top.Controls.Add(tables);Button(top,"Tải lại",()=>LoadTable());Button(top,"Thêm",()=>Edit(false));Button(top,"Sửa",()=>Edit(true));top.Controls.Add(search);Button(top,"Tìm trong bảng",()=>{var dt=grid.DataSource as DataTable;if(dt!=null){var q=search.Text.Replace("'","''").Replace("[","[[]").Replace("%","[%]");dt.DefaultView.RowFilter=string.Join(" OR ",dt.Columns.Cast<DataColumn>().Select(c=>"CONVERT(["+c.ColumnName+"], 'System.String') LIKE '%"+q+"%'"));}});Button(top,"Xuất CSV",Export);Button(top,"Lịch sử NV",()=>grid.DataSource=service.History(id.Text));
 action.Items.AddRange(new object[]{"Ký quyết định","Hoàn tất hợp đồng","Thử việc đạt","Thử việc không đạt","Xác nhận phụ trội","Xác nhận chi thưởng","Xác nhận thu phạt","Tính lương"});action.SelectedIndex=0;top.Controls.Add(action);top.Controls.Add(new Label{Text="Mã hồ sơ / phiếu",AutoSize=true});top.Controls.Add(id);top.Controls.Add(signer);top.Controls.Add(date);Button(top,"Thực hiện",()=>{service.Run(action.Text,id.Text,signer.Text,date.Value);LoadTable();MessageBox.Show("Đã thực hiện.");});tables.SelectedIndexChanged+=(s,e)=>Safe(LoadTable);grid.SelectionChanged+=(s,e)=>{if(grid.CurrentRow!=null&&grid.CurrentRow.Cells.Count>0)id.Text=Convert.ToString(grid.CurrentRow.Cells[0].Value);};Shown+=(s,e)=>tables.SelectedIndex=0;
 var status=new Label{Dock=DockStyle.Bottom,Height=32,Text="Chọn bảng → Thêm/Sửa. Khóa ngoại: dùng mã có sẵn. Ký/xác nhận/tính lương: dùng nút Thực hiện. Hướng dẫn và mã quy ước trong README.",Padding=new Padding(6)};Controls.Add(status);}
 void Safe(Action a){try{a();}catch(Exception ex){MessageBox.Show(ex.Message,"Không thể thực hiện",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 void Button(Control p,string text,Action a){var b=new Button{Text=text,AutoSize=true};b.Click+=(s,e)=>Safe(a);p.Controls.Add(b);}
 void LoadTable(){if(tables.SelectedItem!=null)grid.DataSource=service.List(tables.Text);}
 void Edit(bool edit){if(service.ReadOnly(tables.Text))throw new Exception("Bảng chỉ xem; được sinh khi tính lương.");DataRow row=null;if(edit){var v=grid.CurrentRow==null?null:grid.CurrentRow.DataBoundItem as DataRowView;if(v==null)throw new Exception("Chọn dòng cần sửa.");row=v.Row;}using(var f=new EditorForm(service,tables.Text,row)){if(f.ShowDialog()==DialogResult.OK)LoadTable();}}
 void Export(){var dt=grid.DataSource as DataTable;if(dt==null)return;using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName=tables.Text+".csv"})if(d.ShowDialog()==DialogResult.OK){Func<object,string> esc=v=>"\""+Convert.ToString(v).Replace("\"","\"\"")+"\"";using(var w=new StreamWriter(d.FileName,false,new System.Text.UTF8Encoding(true))){w.WriteLine(string.Join(",",dt.Columns.Cast<DataColumn>().Select(c=>esc(c.ColumnName))));foreach(DataRowView v in dt.DefaultView)w.WriteLine(string.Join(",",v.Row.ItemArray.Select(esc)));}}}
 }
 public class EditorForm:Form {
 readonly Dictionary<string,TextBox> inputs=new Dictionary<string,TextBox>();
 public EditorForm(HrService service,string table,DataRow row){Text=(row==null?"Thêm ":"Sửa ")+table;Width=720;Height=730;StartPosition=FormStartPosition.CenterParent;var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,AutoScroll=true,Padding=new Padding(15)};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,45));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,55));Controls.Add(panel);var schema=service.Columns(table);
 foreach(DataRow c in schema.Rows){string n=(string)c["name"];var t=new TextBox{Width=330};if(row!=null)t.Text=row[n]==DBNull.Value?"":row[n] is DateTime?((DateTime)row[n]).ToString("yyyy-MM-dd"):Convert.ToString(row[n],CultureInfo.InvariantCulture);else if((string)c["type"]=="decimal"|| (string)c["type"]=="int")t.Text="0";else if((string)c["type"]=="date"&&!(bool)c["is_nullable"])t.Text=DateTime.Today.ToString("yyyy-MM-dd");else if(n=="trangThai")t.Text=table=="NhanVien"?"ThuViec":"Nhap";if(n=="heSoTinhLuong")t.Text="1.5";if(n=="soGioCongChuan")t.Text="208";if(n=="ketQuaThuViec"&&row==null)t.Text="Cho";t.ReadOnly=row!=null&&(bool)c["pk"];inputs[n]=t;panel.Controls.Add(new Label{Text=n+((bool)c["is_nullable"]?" (có thể trống)":" *"),AutoSize=true});panel.Controls.Add(t);}
 var save=new Button{Text="Lưu",Width=140,Height=38};panel.Controls.Add(new Label{Text="Ngày: yyyy-MM-dd; số thập phân dùng dấu chấm; giờ HH:mm. Mã và giá trị quy ước xem README.",AutoSize=true});panel.Controls.Add(save);save.Click+=(s,e)=>{try{var values=new Dictionary<string,object>();foreach(DataRow c in schema.Rows){string n=(string)c["name"],v=inputs[n].Text.Trim(),type=(string)c["type"];if(v==""){if(!(bool)c["is_nullable"])throw new Exception("Thiếu "+n);values[n]=DBNull.Value;}else values[n]=type=="decimal"?(object)decimal.Parse(v,CultureInfo.InvariantCulture):type=="int"?int.Parse(v):type=="date"?DateTime.ParseExact(v,"yyyy-MM-dd",CultureInfo.InvariantCulture):type=="time"?(object)TimeSpan.Parse(v):v;}service.Save(table,values,row!=null);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"Kiểm tra dữ liệu");}};}
 }
}